From f74b7c764a81bebe72f007dbff5645f4ce443a9c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Fri, 20 Nov 2026 23:53:14 +0100
Subject: [PATCH] applets/quicklaunch: expand field codes in jump-list actions

Jump-list actions ran their Exec line with CommandLauncherJob, which
leaves field codes like %u in place, and every entry ran the last one in
the menu. Start the chosen action with ApplicationLauncherJob instead.

BUG: 528653
---
 applets/quicklaunch/IconItem.qml      |  4 ++--
 applets/quicklaunch/quicklaunch_p.cpp | 19 +++++++++++++++----
 applets/quicklaunch/quicklaunch_p.h   |  2 +-
 3 files changed, 18 insertions(+), 7 deletions(-)

diff --git a/applets/quicklaunch/IconItem.qml b/applets/quicklaunch/IconItem.qml
index ab6d8aba3..fac0d6b18 100644
--- a/applets/quicklaunch/IconItem.qml
+++ b/applets/quicklaunch/IconItem.qml
@@ -303,13 +303,13 @@ Item {
                     jumpListItems = [];

                     for (var i = 0; i < iconItem.launcher.jumpListActions.length; ++i) {
-                        var action = iconItem.launcher.jumpListActions[i];
+                        const action = iconItem.launcher.jumpListActions[i];
                         var item = menuItemComponent.createObject(iconItem, {
                             "text": action.name,
                             "icon": action.icon
                         }) as PlasmaExtras.MenuItem;
                         item.clicked.connect(function() {
-                            iconItem.logic.openExec(action.exec);
+                            iconItem.logic.openAction(iconItem.url, action.action);
                         });

                         addMenuItem(item, jumpListSeparator);
diff --git a/applets/quicklaunch/quicklaunch_p.cpp b/applets/quicklaunch/quicklaunch_p.cpp
index 68e666100..eb59b273b 100644
--- a/applets/quicklaunch/quicklaunch_p.cpp
+++ b/applets/quicklaunch/quicklaunch_p.cpp
@@ -19,8 +19,9 @@
 #include <KConfig>
 #include <KConfigGroup>
 #include <KDesktopFile>
+#include <KDesktopFileAction>
 #include <KFileItem>
-#include <KIO/CommandLauncherJob>
+#include <KIO/ApplicationLauncherJob>
 #include <KIO/OpenUrlJob>
 #include <KNotificationJobUiDelegate>
 #include <KOpenWithDialog>
@@ -72,7 +73,7 @@ QVariantMap QuicklaunchPrivate::launcherData(const QUrl &url)

                 jumpListActions << QVariantMap{{QStringLiteral("name"), name},
                                                {QStringLiteral("icon"), actionGroup.readEntry("Icon")},
-                                               {QStringLiteral("exec"), exec}};
+                                               {QStringLiteral("action"), actionName}};
             }
         } else {
             QMimeDatabase db;
@@ -106,9 +107,19 @@ void QuicklaunchPrivate::openUrl(const QUrl &url)
     job->start();
 }

-void QuicklaunchPrivate::openExec(const QString &exec)
+void QuicklaunchPrivate::openAction(const QUrl &url, const QString &actionName)
 {
-    KIO::CommandLauncherJob *job = new KIO::CommandLauncherJob(exec);
+    const KDesktopFile desktopFile(url.toLocalFile());
+    const QList<KDesktopFileAction> actions = desktopFile.actions();
+    const auto it = std::find_if(actions.cbegin(), actions.cend(), [&actionName](const KDesktopFileAction &action) {
+        return action.actionsKey() == actionName;
+    });
+    if (it == actions.cend()) {
+        return;
+    }
+
+    // ApplicationLauncherJob expands field codes like %u, unlike CommandLauncherJob
+    auto *job = new KIO::ApplicationLauncherJob(*it);
     job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
     job->start();
 }
diff --git a/applets/quicklaunch/quicklaunch_p.h b/applets/quicklaunch/quicklaunch_p.h
index 0336d0adf..9103905e2 100644
--- a/applets/quicklaunch/quicklaunch_p.h
+++ b/applets/quicklaunch/quicklaunch_p.h
@@ -22,7 +22,7 @@ public:

     Q_INVOKABLE QVariantMap launcherData(const QUrl &url);
     Q_INVOKABLE void openUrl(const QUrl &url);
-    Q_INVOKABLE void openExec(const QString &exec);
+    Q_INVOKABLE void openAction(const QUrl &url, const QString &actionName);

     Q_INVOKABLE void addLauncher(bool isPopup = false);
     Q_INVOKABLE void editLauncher(QUrl url, int index, bool isPopup = false);
-- 
